window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[172]={"id":"172","numero":172,"titre":"Parasitoses digestives","objectifs":[{"id":"172-1","rang":"A","rubrique":"Définition","titre":"Connaître les parasitoses les plus fréquentes responsables d’atteinte intestinale","contenu":"<div class=\"notion-course\"><p><span>Les</span> <span>parasitoses digestives</span> regroupent les infections du tube digestif dues à des <strong><span>protozoaires</span></strong> (parasites unicellulaires) ou à des <strong><span>helminthes</span></strong> (vers). Elles sont essentiellement liées au <strong><span>péril fécal</span></strong>. La fiche source en retient <strong><span>7 principales</span></strong> responsables d'atteinte intestinale.</p>\n      <table>\n        <thead><tr><th>Parasitose</th><th>Agent pathogène</th><th>Groupe</th><th>Transmission en France</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Giardiose</strong></td><td><span><span class=\"nc-purple_bg\">Giardia duodenalis</span></span></td><td><span>Protozoaire</span></td><td><strong>Oui</strong> (cosmopolite)</td></tr>\n          <tr><td><strong>Amœbose</strong></td><td><span><span class=\"nc-purple_bg\">Entamoeba histolytica</span></span></td><td><span>Protozoaire</span></td><td>Le plus souvent importée</td></tr>\n          <tr><td><strong>Cryptosporidiose</strong></td><td><span><span class=\"nc-purple_bg\">Cryptosporidium parvum</span></span></td><td><span>Protozoaire</span></td><td><span class=\"nc-pink nc-bold\">Cosmopolite</span>, surtout tropicale</td></tr>\n          <tr><td><strong>Taeniasis</strong></td><td><span>Taenia saginata</span><br><span>Taenia solium</span></td><td><span>Helminthe — cestode</span></td><td><strong>Oui</strong> pour <span>T. saginata</span> ; <span>T. solium</span> importé</td></tr>\n          <tr><td><strong>Oxyurose</strong></td><td><span>Enterobius vermicularis</span></td><td><span>Helminthe — nématode</span></td><td><strong>Oui</strong> (cosmopolite)</td></tr>\n          <tr><td><strong>Ascaridiose</strong></td><td><span><span class=\"nc-purple_bg\">Ascaris lumbricoides</span></span></td><td><span>Helminthe — nématode</span></td><td>Exceptionnelle (importée)</td></tr>\n          <tr><td><strong>Anguillulose</strong></td><td><span>Strongyloides stercoralis</span></td><td><span>Helminthe — nématode</span></td><td>Importée (zones tropicales)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Rappel — <span>classification</span> des parasites pathogènes pour l'homme.</strong> Le grand discriminant <span>biologique</span> est l'<span>hyperéosinophilie</span> : <strong>absente</strong> dans <span>les</span> parasitoses à protozoaires, <strong>possible</strong> dans les helminthiases.</p>\n      <table>\n        <thead><tr><th>Embranchement</th><th>Sous-groupe</th><th>Exemples digestifs</th><th>Hyperéosinophilie</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Protozoaires</strong><br>(parasites unicellulaires)</td><td>—</td><td><span><span class=\"nc-purple_bg\">Entamoeba histolytica</span></span>, <span><span class=\"nc-purple_bg\">Giardia duodenalis</span></span>, <span><span class=\"nc-purple_bg\">Cryptosporidium parvum</span></span></td><td><span>Absente</span></td></tr>\n          <tr><td><strong>Helminthes</strong> — plathelminthes<br>(vers plats)</td><td><span><span class=\"nc-purple nc-bold\">Cestodes</span></span> (segmentés)</td><td><span><span class=\"nc-green_bg\">Taenia saginata</span></span>, <span><span class=\"nc-orange_bg\">Taenia solium</span></span></td><td><span>Possible</span></td></tr>\n          <tr><td><strong>Helminthes</strong> — plathelminthes<br>(vers plats)</td><td><span>Trématodes</span> (non segmentés)</td><td><span>Douves</span> (distomatose), <span>bilharzies</span></td><td><span>Possible</span></td></tr>\n          <tr><td><strong>Helminthes</strong> — némathelminthes<br>(vers ronds)</td><td><span>Nématodes</span></td><td><span>Enterobius vermicularis</span>, <span><span class=\"nc-purple_bg\">Ascaris lumbricoides</span></span>, <span>Strongyloides stercoralis</span></td><td><span>Possible</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Seules <strong><span class=\"nc-green_bg\">Taenia saginata</span></strong>, l'<strong><span class=\"nc-green_bg\">oxyurose</span></strong> et la <strong><span class=\"nc-green_bg\">giardiose</span></strong> se transmettent couramment en France métropolitaine. <span>Les</span> autres parasitoses intestinales sont le plus souvent <strong>importées</strong> (voyageurs, migrants).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 170 — <span>Paludisme</span> · 175 — Voyage en pays tropical</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 172</a></li></ul></details>","frequence":0},{"id":"172-2","rang":"A","rubrique":"Définition","titre":"Connaître les deux parasitoses responsables d’atteinte hépatique et nommer les agents pathogènes","contenu":"<div class=\"notion-course\"><ul><li>L’amœbose hépatique est un abcès lié à <span class=\"nc-purple_bg\">Entamoeba histolytica</span>, après franchissement intestinal puis dissémination portale. Elle peut apparaître sans diarrhée actuelle ni épisode intestinal symptomatique reconnu.</li><li>L’hydatidose est une échinococcose kystique, généralement due à Echinococcus granulosus sensu lato : contamination par ingestion d’œufs issus du cycle chien–herbivore. L’homme est un hôte intermédiaire accidentel.</li><li>Une lésion kystique hépatique suspecte d’hydatidose ne se ponctionne pas sans stratégie spécialisée. D’autres parasites peuvent atteindre le foie : la liste de ces deux objectifs n’est pas exhaustive.</li></ul><figure class=\"obj-figure\">\n        <img src=\"../assets/images/172/carte-repartition-amoebose-monde.png\" alt=\"Carte du monde montrant la répartition géographique de l&#x27;amœbose : zones d&#x27;endémie réparties sur la ceinture intertropicale (Afrique, Amérique centrale et du Sud, Asie du Sud-Est)\" loading=\"lazy\">\n        <figcaption>Répartition géographique de l'amœbose dans le Monde : pays d'endémie répartis sur la ceinture intertropicale. Source : ANOFEL, fiche source EDN item 172.</figcaption>\n      </figure></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 172</a></li></ul></details>","frequence":0},{"id":"172-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modes de transmission des parasitoses digestives","contenu":"<div class=\"notion-course\"><p><span>Les</span> parasitoses digestives sont <strong>essentiellement liées au <span>péril fécal</span></strong> (transmission <strong>féco-orale</strong>). <strong>Aucun vaccin</strong> n'est disponible ; la prévention repose sur le renforcement des mesures d'<span>hygiène individuelle et collective</span>.</p>\n      <table>\n        <thead><tr><th>Parasitose</th><th>Mode de transmission</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Giardiose</strong></td><td>Indirecte (<span><span class=\"nc-red nc-bold\">eau</span>, <span class=\"nc-red nc-bold\">aliments</span></span>) ; directe (<span class=\"nc-red nc-bold\">mains souillées</span>) ; <strong>transmission interhumaine</strong> et horizontale</td></tr>\n          <tr><td><strong>Amœbose</strong></td><td>Voie <span><span class=\"nc-red nc-bold\">orofécale</span></span> (eau, aliments) ou <strong><span class=\"nc-red nc-bold\">manuportage</span></strong> — <span class=\"nc-blue_bg\">formes kystiques présentes dans le milieu extérieur</span></td></tr>\n          <tr><td><strong>Cryptosporidiose</strong></td><td>Indirecte (<span><span class=\"nc-red nc-bold\">eau</span>, <span class=\"nc-red nc-bold\">aliments</span></span>) ; directe (<span class=\"nc-red nc-bold\">mains souillées</span>)</td></tr>\n          <tr><td><strong>Taeniasis</strong></td><td>Ingestion de <strong>viande parasitée mal cuite ou crue</strong> : bœuf pour <span>T. saginata</span>, porc pour <span>T. solium</span></td></tr>\n          <tr><td><strong>Oxyurose</strong></td><td>Ingestion d'œufs (mains, sous-vêtements, literie) ; <strong>auto-infestation</strong> orale fréquente après grattage anal</td></tr>\n          <tr><td><strong>Ascaridiose</strong></td><td>Ingestion d'œufs présents dans l'eau ou <span>les</span> aliments souillés (<span><span class=\"nc-red nc-bold\">péril fécal</span></span><span class=\"nc-red nc-bold\"> humain</span>)</td></tr>\n          <tr><td><strong>Anguillulose</strong></td><td><strong>Pénétration transcutanée des larves</strong> — <span class=\"nc-red nc-bold\">marche pieds nus sur une terre humide</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant.</strong> L'<strong>anguillulose</strong> est la seule parasitose digestive de cette liste à ne <strong>pas</strong> suivre la voie féco-orale : sa contamination est <strong>transcutanée</strong>. Le taeniasis se distingue aussi : transmission par la <strong>viande</strong>, pas directement par <span>les</span> selles.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 175 — Voyage en pays tropical · 176 — <span>Diarrhée</span> infectieuse</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 172</a></li></ul></details>","frequence":0},{"id":"172-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les manifestations cliniques associées aux parasitoses intestinales (hors amoebose)","contenu":"<div class=\"notion-course\"><p>Présentation clinique des <strong>6 parasitoses intestinales hors amœbose</strong>. Trait commun : elles sont <strong>souvent asymptomatiques</strong>, le portage chronique est fréquent.</p>\n      <table>\n        <thead><tr><th>Parasitose</th><th>Manifestations cliniques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"nc-green_bg\">Giardiose</span></strong></td><td>L’amœbose intestinale est souvent peu ou non fébrile ; une fièvre n’exclut pas une forme compliquée et doit faire chercher une autre infection ou un abcès hépatique.</td></tr>\n          <tr><td><strong>Taeniasis</strong></td><td>\n            <span><span class=\"nc-green_bg\">Asymptomatique</span></span><span class=\"nc-green_bg\"> le plus souvent</span><br>\n            <strong>Digestif :</strong> <span><span class=\"nc-blue_bg\">douleurs abdominales</span></span> ; <span><span class=\"nc-blue_bg\">nausées</span></span> ; <span><span class=\"nc-blue_bg\">troubles de l'appétit</span></span> (non spécifiques)<br>\n            <strong>Cutané :</strong> <span><span class=\"nc-blue_bg\">urticaire</span></span><br>\n            <strong>Signe d'appel :</strong> émission d'<strong><span>anneaux</span></strong> dans <span>les</span> selles, les sous-vêtements, la literie\n          </td></tr>\n          <tr><td><strong><span class=\"nc-green_bg\">Oxyurose</span></strong></td><td>\n            <span><span class=\"nc-green_bg\">Asymptomatique</span></span><span class=\"nc-green_bg\"> le plus souvent</span><br>\n            <strong><span><span class=\"nc-yellow_bg\">Prurit anal vespéral</span></span></strong> — au coucher, lié à la ponte du ver femelle<br>\n            <strong>Fille :</strong> <span><span class=\"nc-yellow_bg\">vulvo-vaginite</span></span><br>\n            <strong>Comportement :</strong> <span><span class=\"nc-orange_bg\">irritabilité</span></span> ; <span>troubles de la concentration</span> ; <span><span class=\"nc-orange_bg\">troubles du sommeil</span></span> — <strong>parfois seule manifestation</strong>\n          </td></tr>\n          <tr><td><strong>Ascaridiose</strong></td><td>\n            <strong>Phase d'invasion :</strong> <span>asymptomatique</span> ; <span>urticaire</span> ; parfois <span><span class=\"nc-orange_bg\">syndrome de Löffler</span></span><br>\n            <strong>Phase d'état :</strong> <span>asymptomatique</span> ou <span>troubles digestifs</span> non spécifiques (<span class=\"nc-blue_bg\">dyspepsie</span>, <span><span class=\"nc-blue_bg\">nausées</span></span>)<br>\n            <strong>Particularité :</strong> <span>les</span> vers adultes peuvent être excrétés par les <strong><span>vomissements</span></strong>\n          </td></tr>\n          <tr><td><strong>Anguillulose</strong></td><td>\n            <span><span class=\"nc-green_bg\">Asymptomatique</span></span><span class=\"nc-green_bg\"> le plus souvent</span><br>\n            <span>Larva <span class=\"nc-yellow_bg nc-bold\">currens</span></span> <span class=\"nc-yellow_bg\">cutanée</span> ; <span>troubles digestifs</span> ; <span><span class=\"nc-orange_bg\">syndrome de Löffler</span></span><br>\n            <em>Circonstances détaillées dans l'objectif dédié à l'anguillulose</em>\n          </td></tr>\n          <tr><td><strong>Cryptosporidiose</strong></td><td>\n            <span><span class=\"nc-blue_bg\">Diarrhée aiguë cholériforme</span></span> ou <span><span class=\"nc-blue_bg\">diarrhée chronique</span></span><br>\n            <em>Circonstances détaillées dans l'objectif dédié à la cryptosporidiose</em>\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Réflexe EDN.</strong> Devant une <strong><span><span class=\"nc-blue_bg\">diarrhée</span></span><span class=\"nc-blue_bg\"> chronique</span> au retour de voyage</strong>, surtout chez l'<span class=\"nc-red nc-bold\">enfant</span>, penser à la <strong><span class=\"nc-green_bg\">giardiose</span></strong> — selles décolorées et malodorantes, sans sang.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 218 — Eosinophilie · 176 — <span>Diarrhée</span> infectieuse</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 172</a></li></ul></details>","frequence":2},{"id":"172-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les circonstances cliniques et épidémiologiques devant faire évoquer une anguillulose","contenu":"<div class=\"notion-course\"><p>Agent : <strong><span>Strongyloides stercoralis</span></strong> (<span>nématode</span>). Géographie : présente dans <strong><span class=\"nc-red nc-bold\">tous </span><span><span class=\"nc-red nc-bold\">les</span></span><span class=\"nc-red nc-bold\"> pays tropicaux</span></strong>.</p>\n      <p><strong>Circonstances évocatrices</strong></p>\n      <ul>\n        <li><strong><span>Épidémiologie</span> :</strong> séjour en <span>zone tropicale</span> ; transmission par <strong>pénétration transcutanée des larves</strong> (<span class=\"nc-red nc-bold\">marche pieds nus sur une terre humide</span>).</li>\n        <li><strong>Clinique :</strong> <span><span class=\"nc-green_bg\">asymptomatique</span></span><span class=\"nc-green_bg\"> le plus souvent</span> ; <strong><span><span class=\"nc-yellow_bg\">syndrome de larva</span> <span class=\"nc-yellow_bg nc-bold\">currens</span> <span class=\"nc-yellow_bg\">cutanée</span></span></strong> (<span><span class=\"nc-yellow_bg\">urticaire</span></span> + <span class=\"nc-yellow_bg\">dermatite rampante</span>) ; <span>troubles digestifs</span> (<span class=\"nc-blue_bg\">douleurs ép</span><span><span class=\"nc-blue_bg\">iga</span></span><span class=\"nc-blue_bg\">striques</span>, <span><span class=\"nc-blue_bg\">diarrhée</span></span>) ; <span><span class=\"nc-orange_bg\">syndrome de Löffler</span></span> plus rarement.</li>\n        <li><strong>Biologie :</strong> <strong><span>hyperéosinophilie oscillante ou cyclique</span></strong> (inconstante) — liée au cycle d'auto-infestation digestive.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Forme grave — anguillulose maligne.</strong> Chez l'<strong><span class=\"nc-red nc-bold\">immunodéprimé</span></strong>, l'auto-infestation s'emballe : forme disséminée souvent <strong><span class=\"nc-red nc-bold\">mortelle</span></strong> — <span><span class=\"nc-red_bg\">encéphalite</span></span>, <span><span class=\"nc-red_bg\">détresse respiratoire</span></span>, <span><span class=\"nc-red_bg\">purpura péri-ombilical</span></span>.</div>\n      <div class=\"callout callout-warn\"><strong>Point EDN majeur.</strong> Dépister et traiter l'anguillulose <strong>avant toute immunosuppression</strong> (<span>corticothérapie</span>, <span>chimiothérapie</span>) chez tout patient ayant séjourné en zone d'endémie — <strong>y compris en l'absence de documentation</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 218 — Eosinophilie · 175 — Voyage en pays tropical</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 172</a></li></ul></details>","frequence":0},{"id":"172-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les circonstances cliniques et épidémiologiques devant faire évoquer une cryptosporidiose","contenu":"<div class=\"notion-course\"><p>Agent : <strong><span><span class=\"nc-purple_bg\">Cryptosporidium parvum</span></span></strong> (protozoaire). Géographie : <span class=\"nc-green_bg\">cosmopolite</span>, plus fréquente dans <span>les</span> régions tropicales.</p>\n      <ul>\n        <li><strong>Transmission :</strong> indirecte (<span><span class=\"nc-red nc-bold\">eau</span>, <span class=\"nc-red nc-bold\">aliments</span></span>) ou directe (<span class=\"nc-red nc-bold\">mains souillées</span>).</li>\n        <li><strong>Clinique :</strong> soit <span><span class=\"nc-blue_bg\">diarrhée aiguë cholériforme</span></span>, soit <span><span class=\"nc-blue_bg\">diarrhée chronique</span></span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Circonstance clé.</strong> Chez l'<strong><span class=\"nc-red nc-bold\">immunodéprimé</span></strong> (<span>VIH</span> notamment), la cryptosporidiose donne des formes <strong>sévères et prolongées</strong> : <span><span class=\"nc-red nc-bold\">malabsorption</span></span>, <span><span class=\"nc-red_bg\">angiocholites</span></span>. Toute <span><span class=\"nc-blue_bg\">diarrhée</span></span><span class=\"nc-blue_bg\"> chronique</span> sur <span>terrain</span> <span class=\"nc-red nc-bold\">immunodéprimé</span> doit la faire évoquer.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 172</a></li></ul></details>","frequence":0},{"id":"172-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les manifestations cliniques associées à l’amoebose intestinale et hépatique","contenu":"<div class=\"notion-course\"><p>L'amœbose à <span><span class=\"nc-purple_bg\">Entamoeba histolytica</span></span> donne deux tableaux distincts, à bien différencier — notamment sur le critère <strong><span>fièvre</span></strong>.</p>\n      <table>\n        <thead><tr><th>Forme</th><th>Manifestations cliniques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Amœbose intestinale aiguë</strong></td><td>L’amœbose intestinale est souvent peu ou non fébrile ; une fièvre n’exclut pas une forme compliquée et doit faire chercher une autre infection ou un abcès hépatique.</td></tr>\n          <tr><td><strong>Amœbose hépatique</strong><br>(<span>abcès</span> amibien)</td><td>\n            Installation <strong>aiguë</strong><br>\n            <strong>Général :</strong> <span><span class=\"nc-red nc-bold\">fièvre élevée</span></span> ; <span><span class=\"nc-yellow_bg\">frissons</span></span><br>\n            <strong>Douleur :</strong> <span>hypochondre droit</span>, <span class=\"nc-blue_bg\">irradiant à l'épaule droite</span><br>\n            <strong>Examen :</strong> <span><span class=\"nc-blue_bg\">hépatomégalie douloureuse</span></span><span class=\"nc-blue_bg\"> à la palpation</span><br>\n            <strong>Respiratoire :</strong> <span><span class=\"nc-blue_bg\">toux sèche</span></span> possible (irritation phrénique)\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Complications de l'amœbose intestinale.</strong> <span>Forme fulminante</span> — <strong><span class=\"nc-red nc-bold\">mortelle</span> dans <span>50 %</span> des cas</strong> ; <span>amœbome</span> (pseudo-tumeur de la fosse iliaque droite) ; <span>colite nécrosante aiguë</span> sur <span>terrain</span> fragile (lésions ulcérées sévères de tout le côlon).</div>\n      <div class=\"callout callout-warn\">L’amœbose intestinale est souvent peu ou non fébrile ; une fièvre n’exclut pas une forme compliquée et doit faire chercher une autre infection ou un abcès hépatique.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 172</a></li></ul></details>","frequence":1},{"id":"172-8","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les complications liées à l’infestation par Tænia solium","contenu":"<div class=\"notion-course\"><ul><li>Le tæniasis à T. solium suit l’ingestion de porc contenant des larves. La cysticercose suit l’ingestion d’œufs, par contamination féco-orale : ce ne sont pas les mêmes formes infectantes.</li><li>Les larves peuvent atteindre <span class=\"nc-red nc-bold\">cerveau</span>, œil et <span class=\"nc-red nc-bold\">muscles</span>. Neurocysticercose : crises épileptiques, céphalées, hydrocéphalie ou hypertension intracrânienne ; imagerie et examens complémentaires spécialisés.</li><li>La prise en charge dépend du nombre, de la localisation, de la viabilité des lésions et de l’inflammation : anticonvulsivants, corticoïdes, parfois antiparasitaires ou chirurgie. Une lésion calcifiée ne se traite pas comme un kyste viable.</li><li>Ne pas appliquer un schéma universel d’<span class=\"nc-pink_bg nc-bold\">albendazole</span>/<span class=\"nc-pink_bg nc-bold\">praziquantel</span> en <span class=\"nc-pink_bg nc-bold\">dose unique</span> : le traitement antiparasitaire d’une neurocysticercose exige un avis spécialisé, notamment après évaluation ophtalmologique.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 172</a></li></ul></details>","frequence":0},{"id":"172-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les moyens diagnostiques de l’amoebose intestinale et hépatique","contenu":"<div class=\"notion-course\"><table>\n        <thead><tr><th>Forme</th><th>Moyens diagnostiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Amœbose intestinale</strong></td><td>\n            <strong><span><span class=\"nc-blue_bg\">EPS</span></span> :</strong> souvent seules <span>les</span> formes kystiques sont vues, <strong>indifférenciables d'<span>E. dispar</span></strong> (non pathogène) ; à réaliser <span>×3</span>, <span class=\"nc-pink nc-bold\">espacés de quelques jours</span>, acheminement rapide au laboratoire (parasite fragile)<br>\n            <strong><span><span class=\"nc-blue_bg\">PCR</span></span> :</strong> <span class=\"nc-blue_bg\">beaucoup plus sensible</span> que l'<span><span class=\"nc-blue_bg\">EPS</span></span>, se généralise<br>\n            <strong><span>Sérologie</span> :</strong> rarement positive (atteinte muqueuse, pas tissulaire)<br>\n            <strong><span>Endoscopie</span> :</strong> <span>rectoscopie</span> — <span><span class=\"nc-yellow_bg\">ulcérations en coup d'ongle</span></span>, <span>abcès « en bouton de chemise »</span> ; <span><span class=\"nc-brown_bg\">coloscopie</span></span> pour le <span>diagnostic différentiel</span> des formes chroniques résistantes\n          </td></tr>\n          <tr><td><strong>Amœbose hépatique</strong></td><td>\n            <strong><span>EPS</span> :</strong> le plus souvent négatif<br>\n            <strong><span>Sérologie</span> anti-amibiens :</strong> fortement positive en général — mais <span>faux négatif possible la 1ʳᵉ semaine</span> d'<span>évolution</span><br>\n            <strong><span><span class=\"nc-blue_bg\">Ponction</span></span><span class=\"nc-blue_bg\"> d'une collection</span> :</strong> si <span><span class=\"nc-red nc-bold\">sérologie</span></span><span class=\"nc-red nc-bold\"> négative</span>, <span class=\"nc-red nc-bold\">risque de </span><span><span class=\"nc-red nc-bold\">rupture</span></span>, <span class=\"nc-red nc-bold\">doute</span> avec un <span>abcès</span> pyogène ou <span class=\"nc-red nc-bold\">absence de réponse</span> au traitement — <span>pus brun chocolat</span>, <span>PCR</span> sur liquide confirmant le diagnostic\n          </td></tr>\n        </tbody>\n      </table>\n      <p><strong>Imagerie de l'amœbose hépatique</strong></p>\n      <ul>\n        <li><strong><span>RXT</span> :</strong> surélévation de la coupole droite ± comblement du cul-de-sac costo-diaphragmatique droit.</li>\n        <li><strong><span><span class=\"nc-blue_bg\">Échographie hépatique</span></span> :</strong> <strong><span>abcès</span> UNIQUE souvent volumineux</strong>, plus rarement multiple.</li>\n        <li><strong><span><span class=\"nc-brown_bg\">TDM hépatique</span></span> :</strong> non indispensable si l'<span>échographie</span> est contributive ; utile si <span>abcès</span> du dôme hépatique (invisible en <span>échographie</span>).</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/172/amoebose-hepatique-abces.png\" alt=\"Coupe TDM abdominale montrant un volumineux abcès amibien hypodense du lobe droit du foie\" loading=\"lazy\">\n        <figcaption><span>Abcès</span> amibien du foie droit au <span>scanner</span> : volumineuse collection hypodense, unique. Source : fiche source EDN item 172 (ANOFEL / Pilly 2023).</figcaption>\n      </figure></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 172</a></li></ul></details>","frequence":0},{"id":"172-10","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les moyens diagnostiques des parasitoses intestinales (hors amoebose)","contenu":"<div class=\"notion-course\"><p>L'examen de base est l'<strong><span><span class=\"nc-blue_bg\">EPS</span></span></strong> (examen parasitologique des selles), à réaliser <span>×3 à quelques jours d'intervalle</span> avec acheminement rapide au laboratoire (parasites fragiles). Certaines recherches nécessitent une <strong>demande spécifique</strong>.</p>\n      <table>\n        <thead><tr><th>Parasitose</th><th>Confirmation diagnostique</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Giardiose</strong></td><td><span><span class=\"nc-blue_bg\">EPS</span></span> (formes végétatives ou kystiques — mais <span><span class=\"nc-blue_bg\">EPS</span></span> <strong>peu sensible</strong>) ; <span><span class=\"nc-blue_bg\">PCR Giardia duodenalis</span></span> bien plus sensible ; <span><span class=\"nc-yellow_bg\">biopsies</span></span><span class=\"nc-yellow_bg\"> jéjunales</span> ou liquide duodénal</td></tr>\n          <tr><td><strong>Taeniasis</strong></td><td><span><span class=\"nc-blue nc-bold\">EPS</span></span> ×3 sur <span>10 jours</span> + <strong><span><span class=\"nc-blue nc-bold\">Scotch test</span></span></strong> ; œufs, anneaux ou embryophores visibles au microscope</td></tr>\n          <tr><td><strong><span class=\"nc-green_bg\">Oxyurose</span></strong></td><td><strong><span><span class=\"nc-blue nc-bold\">Scotch test</span></span></strong> — cellophane adhésive appliquée le matin avant la toilette anale, puis lecture au microscope ; <span><span class=\"nc-brown_bg\">EPS</span></span><span class=\"nc-brown_bg\"> souvent négatif</span> ; vers adultes visibles à l'œil nu</td></tr>\n          <tr><td><strong>Ascaridiose</strong></td><td>Œufs à l'<span>EPS</span> (phase d'état) ; rejet de vers adultes ; à la phase d'invasion, <span>les</span> œufs <strong>ne sont pas encore éliminés</strong> dans les selles</td></tr>\n          <tr><td><strong>Anguillulose</strong></td><td>Technique de <strong><span>Baermann</span></strong> (<span class=\"nc-blue_bg\">recherche des</span> larves) + <span><span class=\"nc-blue_bg\">sérologie spécifique</span></span> — demande spécifique</td></tr>\n          <tr><td><strong>Cryptosporidiose</strong></td><td><span><span class=\"nc-yellow_bg\">PCR spécifique</span></span> ou coloration de <strong><span>Ziehl-Nielsen</span></strong> — demande spécifique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Le <strong><span class=\"nc-blue nc-bold\">Scotch test</span> n'est pas spécifique de l'<span class=\"nc-green_bg\">oxyurose</span></strong> : il peut aussi révéler des anneaux ou des embryophores de Tænia.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 172</a></li></ul></details>","frequence":0},{"id":"172-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités de prescription d’une recherche spécifique d’anguillulose","contenu":"<div class=\"notion-course\"><p>La recherche de <span>Strongyloides stercoralis</span> ne se fait <strong>pas</strong> sur un <span>EPS</span> standard — elle requiert une <strong>demande spécifique</strong> au laboratoire.</p>\n      <ul>\n        <li><strong><span class=\"nc-blue_bg\">Recherche des</span> <span class=\"nc-blue_bg nc-bold\">larves dans </span><span><span class=\"nc-blue_bg nc-bold\">les</span></span><span class=\"nc-blue_bg nc-bold\"> selles</span> :</strong> technique de <strong><span>Baermann</span></strong> — fait l'objet d'une <strong>prescription spécifique</strong>.</li>\n        <li><strong><span><span class=\"nc-blue_bg\">Sérologie spécifique</span></span> :</strong> en <span>complément</span>.</li>\n        <li><strong><span>Hyperéosinophilie</span> :</strong> oscillante ou cyclique, <strong>inconstante</strong> — son absence ne permet pas d'exclure le diagnostic.</li>\n      </ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 172</a></li></ul></details>","frequence":0},{"id":"172-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités de prescription d’une recherche spécifique de cryptosporidiose","contenu":"<div class=\"notion-course\"><p>La recherche de <span><span class=\"nc-purple_bg\">Cryptosporidium parvum</span></span> n'est <strong>pas réalisée en routine</strong> sur un <span>EPS</span> standard : elle <strong><span class=\"nc-blue_bg\">fait l'objet d'une demande spécifique</span></strong> au laboratoire.</p>\n      <ul>\n        <li><strong><span>PCR spécifique</span></strong> de Cryptosporidium ; <strong>ou</strong></li>\n        <li>Recherche d'<strong><span>oocystes</span> dans <span>les</span> selles</strong> par <strong>coloration de <span>Ziehl-Nielsen</span></strong>.</li>\n      </ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 172</a></li></ul></details>","frequence":0},{"id":"172-13","rang":"A","rubrique":"Contenu multimédia","titre":"Aspect macroscopique d’un Tænia sp","contenu":"<div class=\"notion-course\"><ul><li>Les photographies montrent un anneau isolé puis une chaîne de segments de <span class=\"nc-green_bg\">Taenia saginata</span> : ver plat rubané segmenté, dont des anneaux mobiles peuvent être retrouvés hors des selles, dans les sous-vêtements.</li><li>L’identification de l’espèce repose sur l’examen parasitologique adapté ; la description macroscopique seule ne suffit pas toujours. Ne pas confondre avec les petits vers filiformes de l’oxyurose.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 172</a></li></ul></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/amoebic-hepatic-abscess","label":"Radiopaedia : Amoebic hepatic abscess"}]},{"id":"172-14","rang":"B","rubrique":"Contenu multimédia","titre":"Aspect macroscopique d’oxyures","contenu":"<div class=\"notion-course\"><ul><li>La photographie montre des oxyures adultes femelles, petits vers blancs filiformes d’environ un centimètre, visibles à la marge anale ou à la surface des selles.</li><li>Prurit anal nocturne : rechercher par test adhésif le matin avant toilette/défécation selon contexte. Un examen parasitologique standard de selles négatif ne suffit pas à exclure l’oxyurose.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 172</a></li></ul></details>","frequence":0},{"id":"172-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de la giardiose, oxyurose, Taeniasis, ascaridiose","contenu":"<div class=\"notion-course\"><table>\n        <thead><tr><th>Parasitose</th><th>Traitement</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Giardiose</strong></td><td><span><span class=\"nc-pink_bg\">Métronidazole</span></span><span class=\"nc-pink_bg\"> PO</span> <span>5 jours</span><br>Alternative : <span><span class=\"nc-pink_bg\">albendazole</span></span> <span><span class=\"nc-pink nc-bold\">4 jours</span></span></td><td><span class=\"nc-pink_bg\">Retraitement à </span><span><span class=\"nc-pink_bg\">15 jours</span></span><span class=\"nc-pink_bg\"> parfois recommandé</span> (collectivités d'enfants) ; contrôle <span>EPS</span> à distance si la <span>diarrhée</span> persiste</td></tr>\n          <tr><td><strong>Oxyurose</strong></td><td><span><span class=\"nc-pink_bg\">Albendazole</span></span> ou <span><span class=\"nc-pink_bg\">flubendazole</span></span></td><td><strong>Traitement toujours indiqué</strong> + traiter <span>les</span> <strong>sujets contacts</strong> ; <strong>2ᵉ cure systématique <span>2 semaines</span> plus tard</strong> ; mesures associées (ongles courts, <span class=\"nc-green_bg\">brossage</span>, changement de linge)</td></tr>\n          <tr><td><strong>Taeniasis</strong></td><td><span><span class=\"nc-pink_bg\">Praziquantel</span></span><span class=\"nc-pink_bg\"> PO</span></td><td>Parfois en plusieurs cures</td></tr>\n          <tr><td><strong>Ascaridiose</strong></td><td><span><span class=\"nc-pink_bg\">Albendazole</span></span> ou <span>flubendazole</span> PO</td><td>—</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant.</strong> L'<strong>oxyurose</strong> impose une <strong>2ᵉ cure systématique à <span>2 semaines</span></strong> (interruption du cycle d'auto-infestation) et le <strong>traitement des sujets contacts</strong>, même asymptomatiques.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 172</a></li></ul></details>","frequence":0},{"id":"172-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de l’amoebose intestinale et hépatique","contenu":"<div class=\"notion-course\"><p>Amœbose invasive : traitement tissulaire puis <span class=\"nc-pink_bg\">amoebicide de contact</span>. Le portage intestinal asymptomatique documenté d’E. histolytica relève d’une stratégie luminale adaptée ; distinguer E. histolytica des amibes non pathogènes.</p>\n      <table>\n        <thead><tr><th>Forme</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Amœbose intestinale</strong></td><td>\n            <strong>1 — Amœbicide tissulaire :</strong> <span><span class=\"nc-pink_bg\">métronidazole</span></span> <span><span class=\"nc-pink nc-bold\">7 jours</span></span> (inefficace sur <span>les</span> formes kystiques de la lumière digestive)<br>\n            <strong>2 — Amœbicide de <span>contact</span> :</strong> <span><span class=\"nc-pink nc-bold\">paromomycine</span></span> <span><span class=\"nc-pink nc-bold\">10 jours</span></span> (action sur la lumière digestive)\n          </td></tr>\n          <tr><td><strong>Amœbose hépatique</strong></td><td>\n            <span><span class=\"nc-pink_bg\">Métronidazole</span></span> <span><span class=\"nc-pink nc-bold\">10 jours</span></span>, puis amœbicide de <span>contact</span> (<span><span class=\"nc-pink nc-bold\">paromomycine</span></span>) pour éviter <span>les</span> rechutes<br>\n            Alternatives : <span><span class=\"nc-pink_bg\">tinidazole</span></span> ou <span><span class=\"nc-pink_bg\">secnidazole</span></span>\n          </td></tr>\n        </tbody>\n      </table>\n      <p><strong><span>Ponction</span> de l'<span>abcès</span> hépatique.</strong> <strong>Inutile dans la majorité des cas.</strong> Elle est justifiée si : <span>abcès</span> volumineux (<span><span class=\"nc-red nc-bold\">&gt; 10 cm</span></span>), abcès <span class=\"nc-red nc-bold\">hyperalgique</span>, <span><span class=\"nc-red nc-bold\">risque de rupture</span></span>, <span>évolution</span> non favorable sous <span><span class=\"nc-pink_bg\">métronidazole</span></span>, ou <span class=\"nc-red nc-bold\">doute</span> avec un <span>diagnostic différentiel</span> (abcès à pyogène, tumeur nécrosée).</p>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Sans traitement, l'<span>évolution</span> de l'amœbose hépatique est <strong>défavorable</strong>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 172</a></li></ul></details>","frequence":0},{"id":"172-17","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître le principe de la surveillance post-thérapeutique des parasitoses intestinales","contenu":"<div class=\"notion-course\"><ul><li>Surveillance adaptée au parasite, aux symptômes et au risque de réinfection. Giardiose : bilan si persistance/récidive ; tæniasis : vérifier cessation d’émission des anneaux et contrôle indiqué.</li><li>Oxyurose : deuxième cure programmée et mesures familiales/hygiène ; un <span class=\"nc-blue nc-bold\">EPS</span> systématique n’est pas le bon contrôle, le <span class=\"nc-blue nc-bold\">Scotch test</span> étant plus pertinent si persistance du doute.</li><li>Anguillulose : suivi clinique et parasitologique/sérologique spécialisé selon terrain ; ne pas conclure à la guérison sur une seule selle négative.</li><li>Amœbose : vérifier traitement de contact après traitement tissulaire et évolution ; réévaluer une persistance symptomatique plutôt que répéter automatiquement le même traitement.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CMIT · Pilly étudiant, chapitre 172</a></li></ul></details>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Anguillulose avant toute immunosuppression :</strong> chez tout patient ayant séjourné en <span class=\"kw-etio\">zone d’endémie</span>, dépister et traiter une <span class=\"kw-clinique\">anguillulose</span> par <span class=\"kw-ttt\">ivermectine</span> <strong>avant <span class=\"kw-ttt\">corticothérapie</span> ou <span class=\"kw-ttt\">chimiothérapie</span></strong> — y compris sans documentation — sous peine d’<span class=\"kw-alerte\">anguillulose maligne</span> disséminée mortelle.</p><p><strong>Amœbose intestinale :</strong> redouter la <span class=\"kw-alerte\">forme fulminante</span>, mortelle dans <span class=\"kw-chiffre\">50 %</span> des cas.</p><p><strong>Amœbose hépatique :</strong> <span class=\"kw-clinique\">évolution</span> <span class=\"kw-alerte\">défavorable sans traitement</span> ; sous <span class=\"kw-ttt\">métronidazole</span>, <span class=\"kw-clinique\">fièvre</span> et <span class=\"kw-clinique\">douleur</span> régressent en <span class=\"kw-chiffre\">&lt; 3 jours</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Anguillulose maligne</span> de l’<span class=\"kw-etio\">immunodéprimé</span> : forme disséminée souvent <strong>mortelle</strong> — <span class=\"kw-alerte\">encéphalite</span>, <span class=\"kw-alerte\">détresse respiratoire</span>, <span class=\"kw-alerte\">purpura péri-ombilical</span></li><li>Amœbose intestinale : <span class=\"kw-alerte\">forme fulminante</span> (mortelle <span class=\"kw-chiffre\">50 %</span>), <span class=\"kw-alerte\">amœbome</span> (pseudo-tumeur de la fosse iliaque droite), <span class=\"kw-alerte\">colite nécrosante aiguë</span> sur <span class=\"kw-def\">terrain</span> fragile</li><li>Amœbose hépatique : <span class=\"kw-alerte\">abcès à risque de rupture</span> (volumineux <span class=\"kw-chiffre\">&gt; 10 cm</span>, hyperalgique) ; <span class=\"kw-alerte\">faux négatif</span> de la <span class=\"kw-bio\">sérologie</span> la <span class=\"kw-chiffre\">1ʳᵉ semaine</span></li><li>Neurocysticercose (<span class=\"kw-etio\">Taenia solium</span>) : <span class=\"kw-alerte\">crises convulsives</span>, <span class=\"kw-alerte\">HTIC</span>, <span class=\"kw-alerte\">cécité</span> (atteinte oculaire)</li><li><span class=\"kw-alerte\">Syndrome de Löffler</span> (ascaridiose, anguillulose) : <span class=\"kw-clinique\">toux sèche</span>, <span class=\"kw-imagerie\">infiltrats pulmonaires labiles</span></li><li>Giardiose / cryptosporidiose : <span class=\"kw-alerte\">malabsorption</span> ; cryptosporidiose de l’immunodéprimé : <span class=\"kw-alerte\">angiocholites</span></li></ul>","principes":"<p><strong>Cadre :</strong> <span class=\"kw-ttt\">antiparasitaire</span> ciblé per os, le plus souvent en <span class=\"kw-clinique\">ambulatoire</span> ; renforcement des mesures d’<span class=\"kw-clinique\">hygiène</span> individuelle et collective ; <strong>aucun vaccin</strong> disponible.<br><strong>Amœbose — règle des 2 temps :</strong> amœbicide tissulaire (<span class=\"kw-ttt\">métronidazole</span>) PUIS amœbicide de <span class=\"kw-def\">contact</span> (<span class=\"kw-ttt\">paromomycine</span>) actif sur <span class=\"kw-clinique\">les</span> formes kystiques de la lumière digestive.</p><p><strong>Giardiose</strong></p><ul><li><span class=\"kw-ttt\">Métronidazole</span> PO <span class=\"kw-chiffre\">5 jours</span> (alternative <span class=\"kw-ttt\">albendazole</span> <span class=\"kw-chiffre\">4 jours</span>)</li><li>Retraitement à <span class=\"kw-chiffre\">15 jours</span> parfois (collectivités d’enfants)</li><li>Traiter <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">sujets contacts</span> symptomatiques en collectivité</li></ul><p><strong>Oxyurose</strong></p><ul><li><span class=\"kw-ttt\">Albendazole</span> ou <span class=\"kw-ttt\">flubendazole</span> — traitement <strong>toujours indiqué</strong></li><li><strong>Traiter aussi <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">sujets contacts</span></strong> (famille, collectivité)</li><li><strong><span class=\"kw-chiffre\">2ᵉ cure</span> systématique à <span class=\"kw-chiffre\">2 semaines</span></strong></li><li>Mesures : ongles courts, brossage, changement du linge</li></ul><p><strong>Taeniasis</strong></p><ul><li><span class=\"kw-ttt\">Praziquantel</span> PO, parfois en plusieurs cures</li></ul><p><strong>Ascaridiose</strong></p><ul><li><span class=\"kw-ttt\">Albendazole</span> ou <span class=\"kw-ttt\">flubendazole</span> PO</li></ul><p><strong>Anguillulose</strong></p><ul><li><span class=\"kw-ttt\">Ivermectine</span></li><li><span class=\"kw-def\">Dépistage</span>-traitement <strong>avant toute immunosuppression</strong> si séjour en <span class=\"kw-etio\">zone d’endémie</span></li></ul><p><strong>Amœbose intestinale</strong></p><ul><li>1 — <span class=\"kw-ttt\">Métronidazole</span> <span class=\"kw-chiffre\">7 jours</span> (amœbicide tissulaire)</li><li>2 — <span class=\"kw-ttt\">Paromomycine</span> <span class=\"kw-chiffre\">10 jours</span> (amœbicide de <span class=\"kw-def\">contact</span>)</li></ul><p><strong>Amœbose hépatique</strong></p><ul><li><span class=\"kw-ttt\">Métronidazole</span> <span class=\"kw-chiffre\">10 jours</span> puis <span class=\"kw-ttt\">paromomycine</span> (anti-rechute) ; alternatives <span class=\"kw-ttt\">tinidazole</span>, <span class=\"kw-ttt\">secnidazole</span></li><li><span class=\"kw-ttt\">Ponction</span> inutile en règle ; justifiée si <span class=\"kw-clinique\">abcès</span> <span class=\"kw-chiffre\">&gt; 10 cm</span>, hyperalgique, <span class=\"kw-alerte\">à risque de rupture</span>, échec ou doute diagnostique</li></ul><p><strong>Cysticercose (T. solium)</strong></p><ul><li><span class=\"kw-ttt\">Corticothérapie</span> initiale puis <span class=\"kw-ttt\">albendazole</span> ou <span class=\"kw-ttt\">praziquantel</span> per os en dose unique</li></ul>","suivi":"<p><strong>Principe général :</strong> contrôle par <span class=\"kw-bio\">EPS</span> à distance du traitement, surtout en cas de persistance des symptômes.</p><p><strong>Giardiose :</strong> contrôle <span class=\"kw-bio\">EPS</span> à distance si la <span class=\"kw-clinique\">diarrhée</span> persiste ; retraitement à <span class=\"kw-chiffre\">15 jours</span> parfois (collectivités).</p><p><strong>Taeniasis :</strong> vérifier l’absence d’émission d’<span class=\"kw-clinique\">anneaux</span> dans <span class=\"kw-clinique\">les</span> selles pendant les <span class=\"kw-chiffre\">3 mois</span> suivants.</p><p><strong>Oxyurose :</strong> deuxième cure systématique à <span class=\"kw-chiffre\">2 semaines</span> + contrôle <span class=\"kw-bio\">EPS</span> à distance.</p><p><strong>Amœbose :</strong> contrôle <span class=\"kw-bio\">EPS</span> à distance ; sous traitement, <span class=\"kw-clinique\">fièvre</span> et <span class=\"kw-clinique\">douleur</span> régressent en <span class=\"kw-chiffre\">&lt; 3 jours</span>, baisse rapide de la <span class=\"kw-bio\">CRP</span> ; <span class=\"kw-imagerie\">échographie</span> contrôlée seulement si <span class=\"kw-clinique\">évolution</span> défavorable.</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-172.pdf","label":"Collège Pilly — Parasitoses digestives (item 172, PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Manifestation digestive ± hyperéosinophilie — Préciser le caractère des selles et le terrain","detail":"<h4>CAT — Démarche diagnostique des parasitoses digestives — Caractère des selles + <span class=\"kw-def\">terrain</span> → parasite, examen spécifique, traitement</h4>","branches":[{"to":"q-proto","label":"Pas d’hyperéosinophilie → protozoaire","color":"blue"},{"to":"q-helm","label":"Hyperéosinophilie / signes d’helminthiase","color":"blue"}]},{"id":"q-proto","kind":"decision","label":"Protozoaire — caractère des selles + terrain ?","branches":[{"to":"t-amibe-int","label":"Syndrome dysentérique SANS fièvre, pays tropical","color":"amber"},{"to":"t-amibe-hep","label":"Fièvre élevée + douleur hypochondre droit + hépatomégalie","color":"amber"},{"to":"t-giardiose","label":"Diarrhée chronique, selles décolorées sans sang","color":"green"},{"to":"t-crypto","label":"Diarrhée chez immunodéprimé (VIH)","color":"amber"}]},{"id":"t-amibe-int","kind":"terminal","label":"Amœbose intestinale aiguë","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Syndrome dysentérique</span> (forme aiguë, enfant en pays tropical)</li><li>Forme subaiguë : <span class=\"kw-clinique\">douleurs abdominales</span>, <span class=\"kw-clinique\">selles molles peu nombreuses</span></li><li><span class=\"kw-clinique\">Épreintes</span>, <span class=\"kw-clinique\">ténesme</span>, <span class=\"kw-clinique\">toucher rectal douloureux</span></li><li><span class=\"kw-clinique\">Fièvre</span> ABSENTE — signe négatif capital</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">EPS</span> <span class=\"kw-chiffre\">×3</span> espacés de quelques jours, acheminement rapide (formes kystiques indifférenciables d’<span class=\"kw-etio\">E. dispar</span>)</li><li><span class=\"kw-bio\">PCR</span> plus sensible ; <span class=\"kw-bio\">sérologie</span> rarement positive</li></ul><h4>Traitement</h4><ul><li>1 — <span class=\"kw-ttt\">Métronidazole</span> <span class=\"kw-chiffre\">7 jours</span> (amœbicide tissulaire)</li><li>2 — <span class=\"kw-ttt\">Paromomycine</span> <span class=\"kw-chiffre\">10 jours</span> (amœbicide de <span class=\"kw-def\">contact</span>)</li></ul><h4>Complications</h4><ul><li><span class=\"kw-alerte\">Forme fulminante</span> mortelle <span class=\"kw-chiffre\">50 %</span>, <span class=\"kw-alerte\">amœbome</span>, <span class=\"kw-alerte\">colite nécrosante aiguë</span></li></ul>"},{"id":"t-amibe-hep","kind":"terminal","label":"Amœbose hépatique","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Fièvre élevée</span>, <span class=\"kw-clinique\">frissons</span></li><li><span class=\"kw-clinique\">Douleur de l’hypochondre droit</span> irradiant à l’épaule droite</li><li><span class=\"kw-clinique\">Hépatomégalie douloureuse</span> ; <span class=\"kw-clinique\">toux sèche</span> possible</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Sérologie</span> anti-amibiens fortement positive ; <span class=\"kw-alerte\">faux négatif</span> possible la <span class=\"kw-chiffre\">1ʳᵉ semaine</span></li><li><span class=\"kw-bio\">EPS</span> le plus souvent négatif</li><li><span class=\"kw-imagerie\">Échographie</span> : <span class=\"kw-clinique\">abcès</span> unique souvent volumineux ; <span class=\"kw-imagerie\">TDM</span> si <span class=\"kw-clinique\">abcès</span> du dôme</li><li><span class=\"kw-ttt\">Ponction</span> : <span class=\"kw-imagerie\">pus brun chocolat</span>, <span class=\"kw-bio\">PCR</span> sur liquide confirme le diagnostic</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Métronidazole</span> <span class=\"kw-chiffre\">10 jours</span> puis <span class=\"kw-ttt\">paromomycine</span> (anti-rechute)</li><li>Alternatives : <span class=\"kw-ttt\">tinidazole</span>, <span class=\"kw-ttt\">secnidazole</span></li><li><span class=\"kw-ttt\">Ponction</span> si <span class=\"kw-clinique\">abcès</span> <span class=\"kw-chiffre\">&gt; 10 cm</span>, hyperalgique, <span class=\"kw-alerte\">à risque de rupture</span>, échec ou doute diagnostique</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Sous traitement : <span class=\"kw-clinique\">fièvre</span> et <span class=\"kw-clinique\">douleur</span> régressent en <span class=\"kw-chiffre\">&lt; 3 jours</span>, baisse rapide de la <span class=\"kw-bio\">CRP</span></li><li><span class=\"kw-imagerie\">Échographie</span> de contrôle seulement si <span class=\"kw-clinique\">évolution</span> défavorable</li></ul>"},{"id":"t-giardiose","kind":"terminal","label":"Giardiose","color":"green","detail":"<h4>Clinique</h4><ul><li>Souvent <span class=\"kw-clinique\">asymptomatique</span></li><li><span class=\"kw-clinique\">Diarrhée</span> chronique fluctuante, sans glaire ni sang ; <span class=\"kw-clinique\">selles malodorantes et décolorées</span></li><li><span class=\"kw-clinique\">Dyspepsie</span> (douleurs ép<span class=\"kw-chiffre\">iga</span>striques, <span class=\"kw-clinique\">nausées</span>, ballonnement) ; <span class=\"kw-clinique\">pas de fièvre</span></li><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-etio\">enfant</span>, <span class=\"kw-etio\">immunodéprimé</span> ; risque de <span class=\"kw-alerte\">malabsorption</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">EPS</span> <span class=\"kw-chiffre\">×3</span> (peu sensible) ; <span class=\"kw-bio\">PCR Giardia duodenalis</span> bien plus sensible</li><li><span class=\"kw-bio\">Biopsies</span> jéjunales ou liquide duodénal (formes végétatives)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Métronidazole</span> PO <span class=\"kw-chiffre\">5 jours</span> (alternative <span class=\"kw-ttt\">albendazole</span> <span class=\"kw-chiffre\">4 jours</span>)</li><li>Retraitement à <span class=\"kw-chiffre\">15 jours</span> parfois (collectivités d’enfants)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Contrôle <span class=\"kw-bio\">EPS</span> à distance si la <span class=\"kw-clinique\">diarrhée</span> persiste</li></ul>"},{"id":"t-crypto","kind":"terminal","label":"Cryptosporidiose","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Diarrhée aiguë cholériforme</span> ou <span class=\"kw-clinique\">diarrhée chronique</span></li><li>Chez l’<span class=\"kw-etio\">immunodéprimé</span> (<span class=\"kw-etio\">VIH</span>) : <span class=\"kw-alerte\">malabsorption</span>, <span class=\"kw-alerte\">angiocholites</span></li></ul><h4>Paraclinique</h4><ul><li>Demande spécifique : <span class=\"kw-bio\">PCR</span> spécifique ou recherche d’<span class=\"kw-etio\">oocystes</span> par coloration de <span class=\"kw-bio\">Ziehl-Nielsen</span></li></ul><h4>Conduite</h4><ul><li>Renforcement des mesures d’<span class=\"kw-clinique\">hygiène</span> ; rechercher une <span class=\"kw-etio\">immunodépression</span> sous-jacente</li></ul>"},{"id":"q-helm","kind":"decision","label":"Helminthe — signe d’appel ?","branches":[{"to":"t-oxyure","label":"Prurit anal vespéral, enfant en collectivité","color":"green"},{"to":"t-taenia","label":"Anneaux « tagliatelles » dans les selles, viande crue","color":"green"},{"to":"t-anguillulose","label":"Larva currens / bilan avant immunosuppression","color":"red"},{"to":"t-ascaris","label":"Syndrome de Löffler + troubles digestifs","color":"green"}]},{"id":"t-oxyure","kind":"terminal","label":"Oxyurose","color":"green","detail":"<h4>Clinique</h4><ul><li>Souvent <span class=\"kw-clinique\">asymptomatique</span></li><li><span class=\"kw-clinique\">Prurit anal vespéral</span> (ponte du ver femelle au coucher)</li><li><span class=\"kw-clinique\">Vulvo-vaginite</span> chez la fille ; <span class=\"kw-clinique\">troubles du sommeil</span>, <span class=\"kw-clinique\">irritabilité</span></li><li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-etio\">enfant en collectivité</span>, cas groupés</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Scotch test</span> le matin avant la toilette ; <span class=\"kw-bio\">EPS</span> souvent négatif</li><li><span class=\"kw-clinique\">Vers adultes</span> visibles à l’œil nu sur la marge anale</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Albendazole</span> ou <span class=\"kw-ttt\">flubendazole</span> — traitement toujours indiqué</li><li>Traiter aussi <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">sujets contacts</span> ; mesures d’hygiène (ongles courts, linge)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Deuxième cure systématique à <span class=\"kw-chiffre\">2 semaines</span> ; contrôle <span class=\"kw-bio\">EPS</span> à distance</li></ul>"},{"id":"t-taenia","kind":"terminal","label":"Taeniasis","color":"green","detail":"<h4>Clinique</h4><ul><li>Souvent <span class=\"kw-clinique\">asymptomatique</span> ; <span class=\"kw-clinique\">troubles digestifs</span> non spécifiques ; <span class=\"kw-clinique\">urticaire</span></li><li>Émission d’<span class=\"kw-clinique\">anneaux</span> plats blanchâtres (aspect de tagliatelles) dans <span class=\"kw-clinique\">les</span> selles, le linge</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">EPS</span> <span class=\"kw-chiffre\">×3</span> sur <span class=\"kw-chiffre\">10 jours</span> + <span class=\"kw-bio\">Scotch test</span> (œufs, anneaux, embryophores)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Praziquantel</span> PO, parfois en plusieurs cures</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Vérifier l’absence d’émission d’<span class=\"kw-clinique\">anneaux</span> pendant <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 mois</span> suivants</li></ul><h4>Complications</h4><ul><li><span class=\"kw-etio\">Taenia solium</span> → <span class=\"kw-alerte\">cysticercose</span> : neuro (<span class=\"kw-alerte\">crises convulsives</span>, <span class=\"kw-alerte\">HTIC</span>), œil (<span class=\"kw-alerte\">cécité</span>), muscles</li><li>Traitement : <span class=\"kw-ttt\">corticothérapie</span> puis <span class=\"kw-ttt\">albendazole</span> ou <span class=\"kw-ttt\">praziquantel</span> en dose unique</li></ul>"},{"id":"t-anguillulose","kind":"terminal","label":"Anguillulose","color":"red","detail":"<h4>Clinique</h4><ul><li>Souvent <span class=\"kw-clinique\">asymptomatique</span></li><li><span class=\"kw-clinique\">Larva currens</span> cutanée (<span class=\"kw-clinique\">urticaire</span> + dermatite rampante) ; <span class=\"kw-clinique\">troubles digestifs</span> ; <span class=\"kw-alerte\">syndrome de Löffler</span></li><li><span class=\"kw-alerte\">Anguillulose maligne</span> de l’<span class=\"kw-etio\">immunodéprimé</span> : <span class=\"kw-alerte\">encéphalite</span>, <span class=\"kw-alerte\">détresse respiratoire</span>, <span class=\"kw-alerte\">purpura péri-ombilical</span>, souvent mortelle</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Hyperéosinophilie</span> oscillante, inconstante</li><li>Demande spécifique : technique de <span class=\"kw-bio\">Baermann</span> (larves dans <span class=\"kw-clinique\">les</span> selles) + <span class=\"kw-bio\">sérologie</span> spécifique</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Ivermectine</span></li></ul><h4>Conduite</h4><ul><li>Dépister et traiter <strong>avant toute immunosuppression</strong> (<span class=\"kw-ttt\">corticothérapie</span>, <span class=\"kw-ttt\">chimiothérapie</span>) chez tout patient ayant séjourné en <span class=\"kw-etio\">zone d’endémie</span>, même sans documentation</li></ul>"},{"id":"t-ascaris","kind":"terminal","label":"Ascaridiose","color":"green","detail":"<h4>Clinique</h4><ul><li>Phase d’invasion : <span class=\"kw-clinique\">urticaire</span>, <span class=\"kw-alerte\">syndrome de Löffler</span> (fébricule, <span class=\"kw-clinique\">toux sèche</span>, <span class=\"kw-imagerie\">infiltrats pulmonaires labiles</span>)</li><li>Phase d’état : <span class=\"kw-clinique\">troubles digestifs</span> non spécifiques ; <span class=\"kw-clinique\">vers adultes</span> parfois excrétés par <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">vomissements</span></li></ul><h4>Paraclinique</h4><ul><li>Œufs à l’<span class=\"kw-bio\">EPS</span> en phase d’état (absents en phase d’invasion) ; <span class=\"kw-bio\">PCR</span> en laboratoire spécialisé</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Albendazole</span> ou <span class=\"kw-ttt\">flubendazole</span> PO</li></ul>"}]},"cards":[{"i":"2badfbf64bfa","n":172,"o":"172-1","u":"Définition","t":"Connaître les parasitoses les plus fréquentes responsables d’atteinte intestinale","q":"Quel est le principal discriminant biologique permettant de différencier une parasitose à protozoaire d'une helminthiase ?","a":"<div class=\"notion-course\"><p>Le principal discriminant biologique est l'<strong>hyperéosinophilie sanguine</strong>. Elle est toujours <strong>absente</strong> dans les parasitoses à protozoaires, et <strong>possible</strong> dans les helminthiases.</p></div>"},{"i":"437b3b43fca4","n":172,"o":"172-1","u":"Définition","t":"Connaître les parasitoses les plus fréquentes responsables d’atteinte intestinale","q":"Quelle est la définition des parasitoses digestives selon la classification des agents pathogènes ?","a":"<div class=\"notion-course\"><p>Les parasitoses digestives sont des infections du tube digestif causées soit par des <strong>protozoaires</strong> (parasites unicellulaires), soit par des <strong>helminthes</strong> (vers).</p></div>"},{"i":"4b159bea7968","n":172,"o":"172-1","u":"Définition","t":"Connaître les parasitoses les plus fréquentes responsables d’atteinte intestinale","q":"Quelles sont les trois parasitoses intestinales les plus fréquentes et se transmettant couramment en France métropolitaine ?","a":"<div class=\"notion-course\"><p>Les trois parasitoses intestinales se transmettant couramment en France métropolitaine sont la <strong><span class=\"nc-green_bg\">giardiose</span></strong> (due à <em><span class=\"nc-purple_bg\">Giardia duodenalis</span></em>), l'<strong><span class=\"nc-green_bg\">oxyurose</span></strong> (due à <em>Enterobius vermicularis</em>) et le <strong>taeniasis à <em><span class=\"nc-green_bg\">Taenia saginata</span></em></strong>.</p></div>"},{"i":"1d77997ebc0c","n":172,"o":"172-10","u":"Examens complémentaires","t":"Connaître les moyens diagnostiques des parasitoses intestinales (hors amoebose)","q":"Quels sont les méthodes diagnostiques spécifiques de la giardiose ?","a":"<div class=\"notion-course\"><p>Pour la giardiose, le diagnostic peut être confirmé par :</p><ul><li>Un <strong><span class=\"nc-blue_bg\">EPS</span></strong> (recherche de formes végétatives ou kystiques), bien que peu sensible.</li><li>Une <strong><span class=\"nc-blue_bg\">PCR </span><em><span class=\"nc-blue_bg\">Giardia duodenalis</span></em></strong>, <span class=\"nc-blue_bg\">beaucoup plus sensible</span>.</li><li>Plus rarement, des <strong><span class=\"nc-yellow_bg\">biopsies jéjunales</span></strong> ou l'analyse du <strong>liquide duodénal</strong>.</li></ul></div>"},{"i":"4db027f6100f","n":172,"o":"172-10","u":"Examens complémentaires","t":"Connaître les moyens diagnostiques des parasitoses intestinales (hors amoebose)","q":"Quel est l'examen de base pour diagnostiquer les parasitoses intestinales et comment doit-il être réalisé ?","a":"<div class=\"notion-course\"><p>L'examen de base est l'<strong><span class=\"nc-blue_bg\">EPS</span> (examen parasitologique des selles)</strong>. Pour une sensibilité optimale, il doit être réalisé <strong>3 fois</strong> à quelques jours d'intervalle, avec un <strong>acheminement rapide</strong> au laboratoire en raison de la fragilité des parasites.</p></div>"},{"i":"74c91d07b386","n":172,"o":"172-10","u":"Examens complémentaires","t":"Connaître les moyens diagnostiques des parasitoses intestinales (hors amoebose)","q":"Quelles sont les méthodes de confirmation diagnostique de l'anguillulose et de la cryptosporidiose ?","a":"<div class=\"notion-course\"><p>Pour l'anguillulose, le diagnostic repose sur la <strong>technique de Baermann</strong> (<span class=\"nc-blue_bg\">recherche des</span> larves) et une <strong><span class=\"nc-blue_bg\">sérologie spécifique</span></strong>.</p><p>Pour la cryptosporidiose, le diagnostic est confirmé par une <strong><span class=\"nc-yellow_bg\">PCR spécifique</span></strong> ou une <strong>coloration de Ziehl-Nielsen</strong> sur les selles.</p></div>"},{"i":"74e160022884","n":172,"o":"172-10","u":"Examens complémentaires","t":"Connaître les moyens diagnostiques des parasitoses intestinales (hors amoebose)","q":"Quels sont les examens complémentaires pour confirmer une oxyurose ?","a":"<div class=\"notion-course\"><p>Le diagnostic de l'<span class=\"nc-green_bg\">oxyurose</span> est principalement basé sur le <strong><span class=\"nc-blue nc-bold\">Scotch test</span></strong> (cellophane adhésive appliquée le matin avant la toilette anale puis examinée au microscope). Un <strong><span class=\"nc-blue nc-bold\">EPS</span></strong> est souvent négatif pour l'<span class=\"nc-green_bg\">oxyurose</span>. Des <strong>vers adultes</strong> peuvent être visibles à l'œil nu.</p></div>"},{"i":"bfd30aeaa1e4","n":172,"o":"172-10","u":"Examens complémentaires","t":"Connaître les moyens diagnostiques des parasitoses intestinales (hors amoebose)","q":"Comment est diagnostiquée l'ascaridiose ?","a":"<div class=\"notion-course\"><p>Pour l'ascaridiose, le diagnostic repose sur :</p><ul><li>La mise en évidence d'<strong>œufs à l'EPS</strong> durant la phase d'état.</li><li>Le <strong>rejet de vers adultes</strong>.</li></ul><p>Il est important de noter qu'à la phase d'invasion, les œufs ne sont pas encore éliminés dans les selles et l'EPS peut être négatif.</p></div>"},{"i":"d6b8cb863749","n":172,"o":"172-10","u":"Examens complémentaires","t":"Connaître les moyens diagnostiques des parasitoses intestinales (hors amoebose)","q":"Comment diagnostique-t-on un Tæniasis ?","a":"<div class=\"notion-course\"><p>Le diagnostic d'un Tæniasis repose sur :</p><ul><li>Un <strong>EPS ×3 sur 10 jours</strong>, recherchant les œufs, anneaux ou embryophores microscopiques.</li><li>Un <strong><span class=\"nc-blue nc-bold\">Scotch test</span></strong>, qui peut également révéler des anneaux ou des embryophores de Tænia (mais n'est pas spécifique de l'oxyurose).</li></ul></div>"},{"i":"4a47a26a7933","n":172,"o":"172-13","u":"Contenu multimédia","t":"Aspect macroscopique d’un Tænia sp","q":"Quelle est la différence macroscopique notable entre l'émission d'anneaux de Taenia saginata et de Taenia solium ?","a":"<div class=\"notion-course\"><p>La différence réside dans le mode d'émission des anneaux :</p><ul><li>Pour <i><span class=\"nc-green_bg\">Taenia saginata</span></i> : les anneaux sont émis <strong>activement</strong> par l'anus.</li><li>Pour <i><span class=\"nc-orange_bg\">Taenia solium</span></i> : les anneaux sont émis <strong>passivement</strong>.</li></ul></div>"},{"i":"7e2c8f18fc30","n":172,"o":"172-13","u":"Contenu multimédia","t":"Aspect macroscopique d’un Tænia sp","q":"À quel embranchement et quelle classe de parasites les Taenia appartiennent-ils ?","a":"<div class=\"notion-course\"><ul><li>Embranchement des Plathelminthes, classe des <span class=\"nc-purple nc-bold\">Cestodes</span> : vers plats rubanés et segmentés.</li></ul></div>"},{"i":"a8c11d9195cd","n":172,"o":"172-13","u":"Contenu multimédia","t":"Aspect macroscopique d’un Tænia sp","q":"Comment les Taenia se présentent-ils macroscopiquement dans les selles ou les sous-vêtements ?","a":"<div class=\"notion-course\"><p>Les Taenia se présentent sous forme d'<strong>anneaux plats blanchâtres</strong>, décrits comme ayant l'aspect de « <strong><span class=\"nc-yellow_bg\">petites tagliatelles</span></strong> ».</p></div>"},{"i":"afaa5a58b97a","n":172,"o":"172-15","u":"Prise en charge","t":"Connaître les principes du traitement de la giardiose, oxyurose, Taeniasis, ascaridiose","q":"Quel est le traitement de première intention de l'ascaridiose ?","a":"<div class=\"notion-course\"><p>Le traitement de première intention de l'ascaridiose repose sur l'<strong><span class=\"nc-pink_bg\">albendazole</span></strong> ou le <strong><span class=\"nc-pink_bg\">flubendazole</span></strong> par voie orale.</p></div>"},{"i":"b7827b1819f3","n":172,"o":"172-15","u":"Prise en charge","t":"Connaître les principes du traitement de la giardiose, oxyurose, Taeniasis, ascaridiose","q":"Quel est le traitement de première intention de la giardiose et ses particularités ?","a":"<div class=\"notion-course\"><p>Le traitement de première intention de la giardiose repose sur le <strong><span class=\"nc-pink_bg\">métronidazole</span></strong> par voie orale pendant <strong><span class=\"nc-pink nc-bold\">5 jours</span></strong>. Une alternative est l'<strong><span class=\"nc-pink_bg\">albendazole</span></strong> pendant <span class=\"nc-pink nc-bold\">4 jours</span>. Un retraitement à 15 jours est parfois recommandé en collectivité, et un contrôle parasitologique des selles doit être réalisé à distance si la diarrhée persiste.</p></div>"},{"i":"d4b42d632550","n":172,"o":"172-15","u":"Prise en charge","t":"Connaître les principes du traitement de la giardiose, oxyurose, Taeniasis, ascaridiose","q":"Quel est le traitement de première intention du tæniasis ?","a":"<div class=\"notion-course\"><p>Le traitement de première intention du tæniasis est le <strong><span class=\"nc-pink_bg nc-bold\">praziquantel</span></strong> par voie orale, parfois répété en plusieurs cures.</p></div>"},{"i":"f11d028a6590","n":172,"o":"172-15","u":"Prise en charge","t":"Connaître les principes du traitement de la giardiose, oxyurose, Taeniasis, ascaridiose","q":"Comment doit être traitée l'oxyurose et quelles sont les mesures associées ?","a":"<div class=\"notion-course\"><p>Le traitement de l'oxyurose repose sur l'<strong><span class=\"nc-pink_bg\">albendazole</span></strong> ou le <strong><span class=\"nc-pink_bg\">flubendazole</span></strong>. Le traitement est toujours indiqué et doit inclure les sujets contacts. Une <strong>deuxième cure systématique</strong> est impérative <strong>2 semaines</strong> plus tard pour interrompre le cycle d'auto-infestation. Des mesures d'hygiène associées sont essentielles : avoir les ongles courts, <span class=\"nc-green_bg\">brossage</span> des ongles et changement de tout le linge de corps et de lit.</p></div>"},{"i":"290eefc82a21","n":172,"o":"172-2","u":"Définition","t":"Connaître les deux parasitoses responsables d’atteinte hépatique et nommer les agents pathogènes","q":"Dans quel contexte épidémiologique l'amœbose hépatique est-elle la plus fréquente en France ?","a":"<div class=\"notion-course\"><p>En France, l'amœbose hépatique est une pathologie qui touche principalement les <strong>voyageurs</strong> ou les <strong>migrants</strong>. Sa répartition géographique est liée aux <strong>pays d'endémie de la ceinture intertropicale</strong>.</p></div>"},{"i":"7a129f9a1f58","n":172,"o":"172-2","u":"Définition","t":"Connaître les deux parasitoses responsables d’atteinte hépatique et nommer les agents pathogènes","q":"Quel est l'agent pathogène responsable de l'échinococcose hydatique et quelle est sa particularité chez l'homme ?","a":"<div class=\"notion-course\"><ul><li>L’hydatidose est une échinococcose kystique, généralement due à Echinococcus granulosus sensu lato : contamination par ingestion d’œufs issus du cycle chien–herbivore. L’homme est un hôte intermédiaire accidentel.</li></ul></div>"},{"i":"e35b4a8069b9","n":172,"o":"172-2","u":"Définition","t":"Connaître les deux parasitoses responsables d’atteinte hépatique et nommer les agents pathogènes","q":"Quelle est la physiopathologie de l'amœbose hépatique ?","a":"<div class=\"notion-course\"><ul><li>L’amœbose hépatique est un abcès lié à <span class=\"nc-purple_bg\">Entamoeba histolytica</span>, après franchissement intestinal puis dissémination portale. Elle peut apparaître sans diarrhée actuelle ni épisode intestinal symptomatique reconnu.</li></ul></div>"},{"i":"ebe32c4e7a92","n":172,"o":"172-2","u":"Définition","t":"Connaître les deux parasitoses responsables d’atteinte hépatique et nommer les agents pathogènes","q":"Quels sont les deux principaux agents pathogènes responsables de parasitoses digestives pouvant entraîner une atteinte hépatique ?","a":"<div class=\"notion-course\"><p>Les deux principaux agents pathogènes sont :</p><ul><li><strong><em><span class=\"nc-purple_bg\">Entamoeba histolytica</span></em></strong> pour l'amœbose hépatique.</li><li><strong><em>Echinococcus granulosus</em></strong> pour l'<span class=\"nc-purple_bg\">échinococcose hydatique</span>.</li></ul></div>"},{"i":"08f0fd93ae52","n":172,"o":"172-3","u":"Diagnostic positif","t":"Connaître les modes de transmission des parasitoses digestives","q":"Quels sont les modes de transmission spécifiques de la giardiose, de l'amœbose et de la cryptosporidiose ?","a":"<div class=\"notion-course\"><ul><li><strong>Giardiose</strong> : Transmission <strong>indirecte</strong> (<span class=\"nc-red nc-bold\">eau</span>, <span class=\"nc-red nc-bold\">aliments</span>) ou <strong>directe</strong> (<span class=\"nc-red nc-bold\">mains souillées</span>), avec une transmission interhumaine et horizontale.</li><li><strong>Amœbose</strong> : Transmission par la <strong>voie <span class=\"nc-red nc-bold\">orofécale</span></strong> (<span class=\"nc-red nc-bold\">eau</span>, <span class=\"nc-red nc-bold\">aliments</span>) ou par <strong><span class=\"nc-red nc-bold\">manuportage</span></strong>, via les <span class=\"nc-blue_bg\">formes kystiques présentes dans le milieu extérieur</span>.</li><li><strong>Cryptosporidiose</strong> : Transmission <strong>indirecte</strong> (<span class=\"nc-red nc-bold\">eau</span>, <span class=\"nc-red nc-bold\">aliments</span>) ou <strong>directe</strong> (<span class=\"nc-red nc-bold\">mains souillées</span>).</li></ul></div>"},{"i":"8f5e9908c6cd","n":172,"o":"172-3","u":"Diagnostic positif","t":"Connaître les modes de transmission des parasitoses digestives","q":"Quel est le mode de transmission principal des parasitoses digestives en général ?","a":"<div class=\"notion-course\"><p>Le mode de transmission principal des parasitoses digestives est le <strong>péril fécal</strong>, c'est-à-dire la <strong>transmission féco-orale</strong>.</p></div>"},{"i":"95b22bc7f084","n":172,"o":"172-3","u":"Diagnostic positif","t":"Connaître les modes de transmission des parasitoses digestives","q":"Quelle parasitose digestive parmi celles listées se distingue par un mode de contamination non féco-oral ?","a":"<div class=\"notion-course\"><p>L'<strong>anguillulose</strong> est la seule parasitose digestive de cette liste à ne pas suivre la voie féco-orale, sa contamination étant <strong>transcutanée</strong>.</p></div>"},{"i":"b184587f54f0","n":172,"o":"172-3","u":"Diagnostic positif","t":"Connaître les modes de transmission des parasitoses digestives","q":"Comment s'effectue la transmission du taeniasis et de l'oxyurose ?","a":"<div class=\"notion-course\"><ul><li><strong>Taeniasis</strong> : Ingestion de <strong>viande parasitée mal cuite ou crue</strong> (bœuf pour <em>T. saginata</em>, porc pour <em>T. solium</em>).</li><li><strong>Oxyurose</strong> : Ingestion d'œufs (via les mains, sous-vêtements, literie), avec une <strong>auto-infestation orale fréquente</strong> après grattage anal.</li></ul></div>"},{"i":"dc1ed7063220","n":172,"o":"172-3","u":"Diagnostic positif","t":"Connaître les modes de transmission des parasitoses digestives","q":"Quel est le mode de transmission de l'ascaridiose et de l'anguillulose ?","a":"<div class=\"notion-course\"><ul><li><strong>Ascaridiose</strong> : Ingestion d'œufs présents dans l'eau ou les aliments souillés, liée au <strong><span class=\"nc-red nc-bold\">péril fécal humain</span></strong>.</li><li><strong>Anguillulose</strong> : <strong>Pénétration transcutanée des larves</strong>, principalement lors de la <span class=\"nc-red nc-bold\">marche pieds nus sur une terre humide</span>.</li></ul></div>"},{"i":"0b77e0aa18d0","n":172,"o":"172-4","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées aux parasitoses intestinales (hors amoebose)","q":"Comment se manifeste cliniquement une oxyurose ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-green_bg\">oxyurose</span> est le plus souvent <strong>asymptomatique</strong>. La manifestation clinique principale est le <strong><span class=\"nc-yellow_bg\">prurit anal vespéral</span></strong>, lié à la ponte du ver femelle au coucher.</p><p>Chez la fille, une <strong><span class=\"nc-yellow_bg\">vulvo-vaginite</span></strong> est possible. Des troubles comportementaux tels que l'<span class=\"nc-orange_bg\">irritabilité</span>, les troubles de la concentration ou du sommeil peuvent parfois être la seule manifestation.</p></div>"},{"i":"21560f77d905","n":172,"o":"172-4","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées aux parasitoses intestinales (hors amoebose)","q":"Comment se manifeste cliniquement la cryptosporidiose ?","a":"<div class=\"notion-course\"><p>La cryptosporidiose se manifeste principalement par une <strong><span class=\"nc-blue_bg\">diarrhée aiguë cholériforme</span></strong> ou une <strong><span class=\"nc-blue_bg\">diarrhée chronique</span></strong>.</p></div>"},{"i":"25b45daebd51","n":172,"o":"172-4","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées aux parasitoses intestinales (hors amoebose)","q":"Quelle est la présentation clinique de l'anguillulose ?","a":"<div class=\"notion-course\"><p>L'anguillulose est le plus souvent <strong>asymptomatique</strong>. Les manifestations cliniques peuvent inclure :</p><ul><li>Une <strong>larva <span class=\"nc-yellow_bg nc-bold\">currens</span> <span class=\"nc-yellow_bg\">cutanée</span></strong>.</li><li>Des troubles digestifs.</li><li>Un <strong><span class=\"nc-orange_bg\">syndrome de Löffler</span></strong>.</li></ul></div>"},{"i":"61d11580c975","n":172,"o":"172-4","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées aux parasitoses intestinales (hors amoebose)","q":"Quelles sont les manifestations cliniques de l'ascaridiose ?","a":"<div class=\"notion-course\"><p>L'ascaridiose peut se manifester en deux phases :</p><ul><li>La <strong>phase d'invasion</strong> est souvent asymptomatique, mais il peut y avoir une urticaire, et parfois un <strong><span class=\"nc-orange_bg\">syndrome de Löffler</span></strong>.</li><li>La <strong>phase d'état</strong> est également souvent asymptomatique ou se manifeste par des troubles digestifs non spécifiques (<span class=\"nc-blue_bg\">dyspepsie</span>, <span class=\"nc-blue_bg\">nausées</span>).</li><li>Une particularité est l'excrétion des vers adultes par les <strong>vomissements</strong> ou les selles.</li></ul></div>"},{"i":"707959e3efb3","n":172,"o":"172-4","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées aux parasitoses intestinales (hors amoebose)","q":"Quelles sont les manifestations cliniques d'un taeniasis ?","a":"<div class=\"notion-course\"><p>Le taeniasis est le plus souvent <strong>asymptomatique</strong>. Des manifestations non spécifiques peuvent inclure :</p><ul><li>Des troubles digestifs : <span class=\"nc-blue_bg\">douleurs abdominales</span>, <span class=\"nc-blue_bg\">nausées</span>, <span class=\"nc-blue_bg\">troubles de l'appétit</span>.</li><li>Des manifestations cutanées : urticaire.</li><li>Le signe d'appel caractéristique est l'<strong>émission d'anneaux</strong> (proglottis) dans les selles, les sous-vêtements ou la literie.</li></ul></div>"},{"i":"b6e7050cc7b7","n":172,"o":"172-4","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées aux parasitoses intestinales (hors amoebose)","q":"Quelles sont les manifestations cliniques possibles de la giardiose ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-green_bg\">giardiose</span> est souvent <strong>asymptomatique</strong>. En cas de symptômes, elle peut provoquer :</p><ul><li>Une <strong><span class=\"nc-blue_bg\">dyspepsie</span></strong> : <span class=\"nc-blue_bg\">douleurs épigastriques</span>, <span class=\"nc-blue_bg\">nausées</span>, ballonnement post-prandial.</li><li>Une <strong><span class=\"nc-red_bg\">diarrhée chronique</span></strong><span class=\"nc-red_bg\">, fluctuante,</span> sans glaire ni sang, avec des selles malodorantes et décolorées.</li><li>La fièvre est généralement absente.</li><li>Elle peut être associée à la <strong>malnutrition infantile</strong> dans les pays en développement.</li></ul></div>"},{"i":"2c8571354752","n":172,"o":"172-7","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées à l’amoebose intestinale et hépatique","q":"Quelles sont les manifestations cliniques de l'amœbose intestinale aiguë non compliquée ?","a":"<div class=\"notion-course\"><p>L'amœbose intestinale aiguë se manifeste par :</p><ul><li>Un <strong><span class=\"nc-red_bg\">syndrome dysentérique</span></strong> (surtout chez l'<span class=\"nc-red nc-bold\">enfant</span> en pays tropical).</li><li>Des <strong><span class=\"nc-blue_bg\">douleurs abdominales</span></strong>.</li><li>Des <span class=\"nc-blue_bg\">selles molles peu nombreuses</span>, avec une perte de la selle moulée quotidienne.</li><li>Des signes rectaux : <strong><span class=\"nc-blue_bg\">épreintes</span></strong>, <strong><span class=\"nc-blue_bg\">ténesme</span></strong>, et <span class=\"nc-red_bg\">toucher rectal douloureux</span>.</li><li>La <strong>fièvre est ABSENTE</strong>, ce qui est un signe négatif capital.</li></ul></div>"},{"i":"b42668e75947","n":172,"o":"172-7","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées à l’amoebose intestinale et hépatique","q":"Quels sont les signes cliniques de l'amœbose hépatique (abcès amibien) ?","a":"<div class=\"notion-course\"><p>L'amœbose hépatique se caractérise par :</p><ul><li>Des signes généraux : <strong><span class=\"nc-red nc-bold\">fièvre élevée</span></strong> et <strong><span class=\"nc-yellow_bg\">frissons</span></strong>.</li><li>Une douleur de l'<strong>hypochondre droit</strong>, <span class=\"nc-blue_bg\">irradiant à l'épaule droite</span>.</li><li>À l'examen : une <strong><span class=\"nc-blue_bg\">hépatomégalie douloureuse</span></strong><span class=\"nc-blue_bg\"> à la palpation</span>.</li><li>Des signes respiratoires : une <strong><span class=\"nc-blue_bg\">toux sèche</span></strong> possible (par irritation phrénique).</li></ul></div>"},{"i":"bcb881b38a93","n":172,"o":"172-7","u":"Diagnostic positif","t":"Connaître les manifestations cliniques associées à l’amoebose intestinale et hépatique","q":"Quel est le piège diagnostique classique concernant la fièvre dans l'amœbose ?","a":"<div class=\"notion-course\"><p>L’amœbose intestinale est souvent peu ou non fébrile ; une fièvre n’exclut pas une forme compliquée et doit faire chercher une autre infection ou un abcès hépatique.</p></div>"},{"i":"1d381e187800","n":172,"o":"172-5","u":"Diagnostic positif","t":"Connaître les circonstances cliniques et épidémiologiques devant faire évoquer une anguillulose","q":"Quels sont les points essentiels concernant les circonstances cliniques et épidémiologiques devant faire évoquer une anguillulose ?","a":"<div class=\"notion-course\"><p>Agent : <strong><span>Strongyloides stercoralis</span></strong> (<span>nématode</span>). Géographie : présente dans <strong><span class=\"nc-red nc-bold\">tous </span><span><span class=\"nc-red nc-bold\">les</span></span><span class=\"nc-red nc-bold\"> pays tropicaux</span></strong>.</p>\n      <p><strong>Circonstances évocatrices</strong></p>\n      <ul>\n        <li><strong><span>Épidémiologie</span> :</strong> séjour en <span>zone tropicale</span> ; transmission par <strong>pénétration transcutanée des larves</strong> (<span class=\"nc-red nc-bold\">marche pieds nus sur une terre humide</span>).</li>\n        <li><strong>Clinique :</strong> <span><span class=\"nc-green_bg\">asymptomatique</span></span><span class=\"nc-green_bg\"> le plus souvent</span> ; <strong><span><span class=\"nc-yellow_bg\">syndrome de larva</span> <span class=\"nc-yellow_bg nc-bold\">currens</span> <span class=\"nc-yellow_bg\">cutanée</span></span></strong> (<span><span class=\"nc-yellow_bg\">urticaire</span></span> + <span class=\"nc-yellow_bg\">dermatite rampante</span>) ; <span>troubles digestifs</span> (<span class=\"nc-blue_bg\">douleurs ép</span><span><span class=\"nc-blue_bg\">iga</span></span><span class=\"nc-blue_bg\">striques</span>, <span><span class=\"nc-blue_bg\">diarrhée</span></span>) ; <span><span class=\"nc-orange_bg\">syndrome de Löffler</span></span> plus rarement.</li>\n        <li><strong>Biologie :</strong> <strong><span>hyperéosinophilie oscillante ou cyclique</span></strong> (inconstante) — liée au cycle d'auto-infestation digestive.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Forme grave — anguillulose maligne.</strong> Chez l'<strong><span class=\"nc-red nc-bold\">immunodéprimé</span></strong>, l'auto-infestation s'emballe : forme disséminée souvent <strong><span class=\"nc-red nc-bold\">mortelle</span></strong> — <span><span class=\"nc-red_bg\">encéphalite</span></span>, <span><span class=\"nc-red_bg\">détresse respiratoire</span></span>, <span><span class=\"nc-red_bg\">purpura péri-ombilical</span></span>.</div>\n      <div class=\"callout callout-warn\"><strong>Point EDN majeur.</strong> Dépister et traiter l'anguillulose <strong>avant toute immunosuppression</strong> (<span>corticothérapie</span>, <span>chimiothérapie</span>) chez tout patient ayant séjourné en zone d'endémie — <strong>y compris en l'absence de documentation</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 218 — Eosinophilie · 175 — Voyage en pays tropical</em></p></div>"},{"i":"2afc989551e0","n":172,"o":"172-6","u":"Diagnostic positif","t":"Connaître les circonstances cliniques et épidémiologiques devant faire évoquer une cryptosporidiose","q":"Quels sont les points essentiels concernant les circonstances cliniques et épidémiologiques devant faire évoquer une cryptosporidiose ?","a":"<div class=\"notion-course\"><p>Agent : <strong><span><span class=\"nc-purple_bg\">Cryptosporidium parvum</span></span></strong> (protozoaire). Géographie : <span class=\"nc-green_bg\">cosmopolite</span>, plus fréquente dans <span>les</span> régions tropicales.</p>\n      <ul>\n        <li><strong>Transmission :</strong> indirecte (<span><span class=\"nc-red nc-bold\">eau</span>, <span class=\"nc-red nc-bold\">aliments</span></span>) ou directe (<span class=\"nc-red nc-bold\">mains souillées</span>).</li>\n        <li><strong>Clinique :</strong> soit <span><span class=\"nc-blue_bg\">diarrhée aiguë cholériforme</span></span>, soit <span><span class=\"nc-blue_bg\">diarrhée chronique</span></span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Circonstance clé.</strong> Chez l'<strong><span class=\"nc-red nc-bold\">immunodéprimé</span></strong> (<span>VIH</span> notamment), la cryptosporidiose donne des formes <strong>sévères et prolongées</strong> : <span><span class=\"nc-red nc-bold\">malabsorption</span></span>, <span><span class=\"nc-red_bg\">angiocholites</span></span>. Toute <span><span class=\"nc-blue_bg\">diarrhée</span></span><span class=\"nc-blue_bg\"> chronique</span> sur <span>terrain</span> <span class=\"nc-red nc-bold\">immunodéprimé</span> doit la faire évoquer.</div></div>"},{"i":"1f48a47ea43a","n":172,"o":"172-8","u":"Diagnostic positif","t":"Connaître les complications liées à l’infestation par Tænia solium","q":"Quels sont les points essentiels concernant les complications liées à l’infestation par Tænia solium ?","a":"<div class=\"notion-course\"><ul><li>Le tæniasis à T. solium suit l’ingestion de porc contenant des larves. La cysticercose suit l’ingestion d’œufs, par contamination féco-orale : ce ne sont pas les mêmes formes infectantes.</li><li>Les larves peuvent atteindre <span class=\"nc-red nc-bold\">cerveau</span>, œil et <span class=\"nc-red nc-bold\">muscles</span>. Neurocysticercose : crises épileptiques, céphalées, hydrocéphalie ou hypertension intracrânienne ; imagerie et examens complémentaires spécialisés.</li><li>La prise en charge dépend du nombre, de la localisation, de la viabilité des lésions et de l’inflammation : anticonvulsivants, corticoïdes, parfois antiparasitaires ou chirurgie. Une lésion calcifiée ne se traite pas comme un kyste viable.</li><li>Ne pas appliquer un schéma universel d’<span class=\"nc-pink_bg nc-bold\">albendazole</span>/<span class=\"nc-pink_bg nc-bold\">praziquantel</span> en <span class=\"nc-pink_bg nc-bold\">dose unique</span> : le traitement antiparasitaire d’une neurocysticercose exige un avis spécialisé, notamment après évaluation ophtalmologique.</li></ul></div>"},{"i":"1e9fce1191d8","n":172,"o":"172-9","u":"Examens complémentaires","t":"Connaître les moyens diagnostiques de l’amoebose intestinale et hépatique","q":"Quels sont les points essentiels concernant les moyens diagnostiques de l’amoebose intestinale et hépatique ?","a":"<div class=\"notion-course\"><table>\n        <thead><tr><th>Forme</th><th>Moyens diagnostiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Amœbose intestinale</strong></td><td>\n            <strong><span><span class=\"nc-blue_bg\">EPS</span></span> :</strong> souvent seules <span>les</span> formes kystiques sont vues, <strong>indifférenciables d'<span>E. dispar</span></strong> (non pathogène) ; à réaliser <span>×3</span>, <span class=\"nc-pink nc-bold\">espacés de quelques jours</span>, acheminement rapide au laboratoire (parasite fragile)<br>\n            <strong><span><span class=\"nc-blue_bg\">PCR</span></span> :</strong> <span class=\"nc-blue_bg\">beaucoup plus sensible</span> que l'<span><span class=\"nc-blue_bg\">EPS</span></span>, se généralise<br>\n            <strong><span>Sérologie</span> :</strong> rarement positive (atteinte muqueuse, pas tissulaire)<br>\n            <strong><span>Endoscopie</span> :</strong> <span>rectoscopie</span> — <span><span class=\"nc-yellow_bg\">ulcérations en coup d'ongle</span></span>, <span>abcès « en bouton de chemise »</span> ; <span><span class=\"nc-brown_bg\">coloscopie</span></span> pour le <span>diagnostic différentiel</span> des formes chroniques résistantes\n          </td></tr>\n          <tr><td><strong>Amœbose hépatique</strong></td><td>\n            <strong><span>EPS</span> :</strong> le plus souvent négatif<br>\n            <strong><span>Sérologie</span> anti-amibiens :</strong> fortement positive en général — mais <span>faux négatif possible la 1ʳᵉ semaine</span> d'<span>évolution</span><br>\n            <strong><span><span class=\"nc-blue_bg\">Ponction</span></span><span class=\"nc-blue_bg\"> d'une collection</span> :</strong> si <span><span class=\"nc-red nc-bold\">sérologie</span></span><span class=\"nc-red nc-bold\"> négative</span>, <span class=\"nc-red nc-bold\">risque de </span><span><span class=\"nc-red nc-bold\">rupture</span></span>, <span class=\"nc-red nc-bold\">doute</span> avec un <span>abcès</span> pyogène ou <span class=\"nc-red nc-bold\">absence de réponse</span> au traitement — <span>pus brun chocolat</span>, <span>PCR</span> sur liquide confirmant le diagnostic\n          </td></tr>\n        </tbody>\n      </table>\n      <p><strong>Imagerie de l'amœbose hépatique</strong></p>\n      <ul>\n        <li><strong><span>RXT</span> :</strong> surélévation de la coupole droite ± comblement du cul-de-sac costo-diaphragmatique droit.</li>\n        <li><strong><span><span class=\"nc-blue_bg\">Échographie hépatique</span></span> :</strong> <strong><span>abcès</span> UNIQUE souvent volumineux</strong>, plus rarement multiple.</li>\n        <li><strong><span><span class=\"nc-brown_bg\">TDM hépatique</span></span> :</strong> non indispensable si l'<span>échographie</span> est contributive ; utile si <span>abcès</span> du dôme hépatique (invisible en <span>échographie</span>).</li>\n      </ul>\n      </div>"},{"i":"91bea8284aba","n":172,"o":"172-11","u":"Examens complémentaires","t":"Connaître les modalités de prescription d’une recherche spécifique d’anguillulose","q":"Quels sont les points essentiels concernant les modalités de prescription d’une recherche spécifique d’anguillulose ?","a":"<div class=\"notion-course\"><p>La recherche de <span>Strongyloides stercoralis</span> ne se fait <strong>pas</strong> sur un <span>EPS</span> standard — elle requiert une <strong>demande spécifique</strong> au laboratoire.</p>\n      <ul>\n        <li><strong><span class=\"nc-blue_bg\">Recherche des</span> <span class=\"nc-blue_bg nc-bold\">larves dans </span><span><span class=\"nc-blue_bg nc-bold\">les</span></span><span class=\"nc-blue_bg nc-bold\"> selles</span> :</strong> technique de <strong><span>Baermann</span></strong> — fait l'objet d'une <strong>prescription spécifique</strong>.</li>\n        <li><strong><span><span class=\"nc-blue_bg\">Sérologie spécifique</span></span> :</strong> en <span>complément</span>.</li>\n        <li><strong><span>Hyperéosinophilie</span> :</strong> oscillante ou cyclique, <strong>inconstante</strong> — son absence ne permet pas d'exclure le diagnostic.</li>\n      </ul></div>"},{"i":"04b81bf35402","n":172,"o":"172-12","u":"Examens complémentaires","t":"Connaître les modalités de prescription d’une recherche spécifique de cryptosporidiose","q":"Quels sont les points essentiels concernant les modalités de prescription d’une recherche spécifique de cryptosporidiose ?","a":"<div class=\"notion-course\"><p>La recherche de <span><span class=\"nc-purple_bg\">Cryptosporidium parvum</span></span> n'est <strong>pas réalisée en routine</strong> sur un <span>EPS</span> standard : elle <strong><span class=\"nc-blue_bg\">fait l'objet d'une demande spécifique</span></strong> au laboratoire.</p>\n      <ul>\n        <li><strong><span>PCR spécifique</span></strong> de Cryptosporidium ; <strong>ou</strong></li>\n        <li>Recherche d'<strong><span>oocystes</span> dans <span>les</span> selles</strong> par <strong>coloration de <span>Ziehl-Nielsen</span></strong>.</li>\n      </ul></div>"},{"i":"26379b84b23d","n":172,"o":"172-14","u":"Contenu multimédia","t":"Aspect macroscopique d’oxyures","q":"Quels sont les points essentiels concernant aspect macroscopique d’oxyures ?","a":"<div class=\"notion-course\"><ul><li>La photographie montre des oxyures adultes femelles, petits vers blancs filiformes d’environ un centimètre, visibles à la marge anale ou à la surface des selles.</li><li>Prurit anal nocturne : rechercher par test adhésif le matin avant toilette/défécation selon contexte. Un examen parasitologique standard de selles négatif ne suffit pas à exclure l’oxyurose.</li></ul></div>"},{"i":"88e5805ceee7","n":172,"o":"172-16","u":"Prise en charge","t":"Connaître les principes du traitement de l’amoebose intestinale et hépatique","q":"Quels sont les points essentiels concernant les principes du traitement de l’amoebose intestinale et hépatique ?","a":"<div class=\"notion-course\"><p>Amœbose invasive : traitement tissulaire puis <span class=\"nc-pink_bg\">amoebicide de contact</span>. Le portage intestinal asymptomatique documenté d’E. histolytica relève d’une stratégie luminale adaptée ; distinguer E. histolytica des amibes non pathogènes.</p>\n      <table>\n        <thead><tr><th>Forme</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Amœbose intestinale</strong></td><td>\n            <strong>1 — Amœbicide tissulaire :</strong> <span><span class=\"nc-pink_bg\">métronidazole</span></span> <span><span class=\"nc-pink nc-bold\">7 jours</span></span> (inefficace sur <span>les</span> formes kystiques de la lumière digestive)<br>\n            <strong>2 — Amœbicide de <span>contact</span> :</strong> <span><span class=\"nc-pink nc-bold\">paromomycine</span></span> <span><span class=\"nc-pink nc-bold\">10 jours</span></span> (action sur la lumière digestive)\n          </td></tr>\n          <tr><td><strong>Amœbose hépatique</strong></td><td>\n            <span><span class=\"nc-pink_bg\">Métronidazole</span></span> <span><span class=\"nc-pink nc-bold\">10 jours</span></span>, puis amœbicide de <span>contact</span> (<span><span class=\"nc-pink nc-bold\">paromomycine</span></span>) pour éviter <span>les</span> rechutes<br>\n            Alternatives : <span><span class=\"nc-pink_bg\">tinidazole</span></span> ou <span><span class=\"nc-pink_bg\">secnidazole</span></span>\n          </td></tr>\n        </tbody>\n      </table>\n      <p><strong><span>Ponction</span> de l'<span>abcès</span> hépatique.</strong> <strong>Inutile dans la majorité des cas.</strong> Elle est justifiée si : <span>abcès</span> volumineux (<span><span class=\"nc-red nc-bold\">&gt; 10 cm</span></span>), abcès <span class=\"nc-red nc-bold\">hyperalgique</span>, <span><span class=\"nc-red nc-bold\">risque de rupture</span></span>, <span>évolution</span> non favorable sous <span><span class=\"nc-pink_bg\">métronidazole</span></span>, ou <span class=\"nc-red nc-bold\">doute</span> avec un <span>diagnostic différentiel</span> (abcès à pyogène, tumeur nécrosée).</p>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Sans traitement, l'<span>évolution</span> de l'amœbose hépatique est <strong>défavorable</strong>.</div></div>"},{"i":"33694ff01877","n":172,"o":"172-17","u":"Suivi et/ou pronostic","t":"Connaître le principe de la surveillance post-thérapeutique des parasitoses intestinales","q":"Quels sont les points essentiels concernant le principe de la surveillance post-thérapeutique des parasitoses intestinales ?","a":"<div class=\"notion-course\"><ul><li>Surveillance adaptée au parasite, aux symptômes et au risque de réinfection. Giardiose : bilan si persistance/récidive ; tæniasis : vérifier cessation d’émission des anneaux et contrôle indiqué.</li><li>Oxyurose : deuxième cure programmée et mesures familiales/hygiène ; un <span class=\"nc-blue nc-bold\">EPS</span> systématique n’est pas le bon contrôle, le <span class=\"nc-blue nc-bold\">Scotch test</span> étant plus pertinent si persistance du doute.</li><li>Anguillulose : suivi clinique et parasitologique/sérologique spécialisé selon terrain ; ne pas conclure à la guérison sur une seule selle négative.</li><li>Amœbose : vérifier traitement de contact après traitement tissulaire et évolution ; réévaluer une persistance symptomatique plutôt que répéter automatiquement le même traitement.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d94181cabcfaf9093d826fb1?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
